from __future__ import absolute_import

"""
Helpers for the Splunk Web access policy used by the Splunk Lite experience.
"""

import cherrypy
import fnmatch
import logging
import re

import splunk.entity as entity
import splunk.appserver.mrsparkle.lib.util as util
from splunk.rest.splunk_web_requests import get_web_access_policy_settings
import splunk.util
from future.moves.urllib import parse as urllib_parse

logger = logging.getLogger('splunk.appserver.mrsparkle.lib.web_access_policy')

_WEB_ACCESS_POLICY_CONTROL_CHAR_PATTERN = re.compile(r'[\x00-\x1f\x7f]')
_WEB_ACCESS_POLICY_EXCLUDED_PREFIXES = (
    '/account',
    '/static',
    '/modules',
    '/services',
    '/servicesNS',
    '/splunkd',
)


# Normalize config values into a clean list of semicolon-delimited entries.
def _parse_semicolon_delimited_config(value):
    if isinstance(value, bytes):
        value = value.decode('utf-8', 'ignore')
    if not isinstance(value, splunk.util.string_type):
        return []

    entries = []
    for entry in value.split(';'):
        entry = entry.strip()
        if entry:
            entries.append(entry)
    return entries


# Validate and normalize a safe internal relative URL.
def _normalize_internal_relative_url(value):
    if isinstance(value, bytes):
        value = value.decode('utf-8', 'ignore')
    if not isinstance(value, str):
        return None

    value = value.strip()
    if (
        not value
        or bool(_WEB_ACCESS_POLICY_CONTROL_CHAR_PATTERN.search(value))
        or '\\' in value
        or not util.url_has_valid_charset(value)
        or not splunk.util.isRedirectSafe(value)
    ):
        return None

    return util.make_url_internal(value)


# Normalize the configured redirect target and reject wildcard targets.
def _normalize_policy_target_url(value):
    normalized_target_url = _normalize_internal_relative_url(value)
    if not normalized_target_url or '*' in normalized_target_url:
        return None

    target_parts = urllib_parse.urlsplit(normalized_target_url)
    normalized_target_path = normalize_web_access_policy_request_path(target_parts.path)
    return urllib_parse.urlunsplit((
        '',
        '',
        normalized_target_path,
        target_parts.query,
        target_parts.fragment,
    ))


# Normalize denylist URL patterns into matchable internal paths.
def _normalize_policy_denylist_patterns(value):
    normalized_patterns = []

    for pattern in _parse_semicolon_delimited_config(value):
        if not pattern.startswith('/'):
            continue

        normalized_pattern = _normalize_internal_relative_url(pattern)
        if not normalized_pattern:
            continue

        normalized_pattern_path = urllib_parse.urlsplit(normalized_pattern).path or normalized_pattern
        normalized_patterns.append(normalized_pattern_path)

    return normalized_patterns


# Normalize the current request path for policy matching.
def normalize_web_access_policy_request_path(path=None):
    request = cherrypy.request
    normalized_path = request.path_info if path is None else path
    if isinstance(normalized_path, bytes):
        normalized_path = normalized_path.decode('utf-8', 'ignore')
    if not isinstance(normalized_path, str):
        return '/'

    # Ignore query parameters and fragments when matching policy routes.
    normalized_path = urllib_parse.urlsplit(normalized_path).path or '/'

    if request.script_name and normalized_path.startswith(request.script_name):
        normalized_path = normalized_path[len(request.script_name):]

    if not normalized_path.startswith('/'):
        normalized_path = '/' + normalized_path

    try:
        locale_prefix = '/{}'.format(util.current_lang_url_component())
        if normalized_path == locale_prefix:
            return '/'
        if normalized_path.startswith(locale_prefix + '/'):
            normalized_path = normalized_path[len(locale_prefix):]
    except Exception:
        pass

    return normalized_path or '/'


# Skip routes where the policy must never redirect.
def _is_excluded_web_access_policy_path(request_path, target_path):
    if request_path == target_path:
        return True

    if util.is_api() or util.is_xhr():
        return True

    if cherrypy.request.method.upper() not in ('GET', 'HEAD'):
        return True

    for prefix in _WEB_ACCESS_POLICY_EXCLUDED_PREFIXES:
        if request_path == prefix or request_path.startswith(prefix + '/'):
            return True

    return False


# Read and normalize list-like values from Splunk entity fields.
def _get_entity_field_list(entity_value, field_name):
    if entity_value is None:
        return []

    properties = getattr(entity_value, 'properties', {})
    if field_name in properties:
        value = properties.get(field_name)
    elif hasattr(entity_value, 'get'):
        value = entity_value.get(field_name)
    else:
        try:
            value = entity_value[field_name]
        except Exception:
            value = None

    if isinstance(value, (list, tuple, set)):
        values = value
    elif isinstance(value, bytes):
        values = splunk.util.stringToFieldList(value.decode('utf-8', 'ignore'))
    elif isinstance(value, splunk.util.string_type):
        values = splunk.util.stringToFieldList(value)
    else:
        return []

    normalized_values = []
    for item in values:
        if isinstance(item, bytes):
            item = item.decode('utf-8', 'ignore')
        if isinstance(item, str):
            item = item.strip()
            if item:
                normalized_values.append(item)
    return normalized_values


# Expand direct roles into effective roles, including imported roles.
def _resolve_effective_roles(role_names, session_key, visited=None):
    effective_roles = set()
    visited = set() if visited is None else visited

    for role_name in role_names:
        if role_name in visited:
            continue

        visited.add(role_name)
        effective_roles.add(role_name)

        role_entity = entity.getEntity('authorization/roles', role_name, sessionKey=session_key)
        imported_roles = _get_entity_field_list(role_entity, 'imported_roles')
        effective_roles.update(_resolve_effective_roles(imported_roles, session_key, visited))

    return effective_roles


# Resolve the current user's directly assigned roles.
def _get_current_user_direct_roles(session_key):
    current_user = (cherrypy.session.get('user') or {}).get('name')
    if not current_user:
        return []

    user_entity = entity.getEntity('authentication/users', current_user, sessionKey=session_key)
    return _get_entity_field_list(user_entity, 'roles')


# Resolve the current user's effective roles from direct and imported roles.
def _get_current_user_effective_roles(session_key, direct_roles=None):
    if direct_roles is None:
        direct_roles = _get_current_user_direct_roles(session_key)
    return _resolve_effective_roles(direct_roles, session_key)


# Decide whether the current authenticated request should redirect.
def get_web_access_policy_redirect_target(session_key, log_safe):
    try:
        # Fail open if the web-features lookup is temporarily unavailable.
        policy_settings = get_web_access_policy_settings(session_key)
    except Exception as e:
        logger.warning(
            'web_access_policy - failed to load policy settings for user=%s path=%s error=%s',
            log_safe((cherrypy.session.get('user') or {}).get('name')),
            log_safe(normalize_web_access_policy_request_path(), treat_as_url=True),
            log_safe(str(e)),
        )
        return None

    if not policy_settings:
        return None

    try:
        if splunk.util.normalizeBoolean(policy_settings.get('enabled'), True) is not True:
            return None
    except ValueError:
        return None

    required_roles = set(_parse_semicolon_delimited_config(policy_settings.get('required_roles')))
    if not required_roles:
        logger.warning('web_access_policy - enabled policy is missing required_roles')
        return None

    bypass_roles = set(_parse_semicolon_delimited_config(policy_settings.get('bypass_roles')))

    target_url = _normalize_policy_target_url(policy_settings.get('target_url'))
    if not target_url:
        logger.warning(
            'web_access_policy - ignoring invalid target_url=%s',
            log_safe(policy_settings.get('target_url'), treat_as_url=True),
        )
        return None

    target_path = urllib_parse.urlsplit(target_url).path or target_url
    request_path = normalize_web_access_policy_request_path()
    if _is_excluded_web_access_policy_path(request_path, target_path):
        return None

    try:
        current_user_direct_roles = set(_get_current_user_direct_roles(session_key))
        if current_user_direct_roles.intersection(bypass_roles):
            return None

        current_user_effective_roles = _get_current_user_effective_roles(
            session_key,
            direct_roles=current_user_direct_roles,
        )
    except Exception as e:
        logger.warning(
            'web_access_policy - failed to resolve roles for user=%s path=%s error=%s',
            log_safe((cherrypy.session.get('user') or {}).get('name')),
            log_safe(request_path, treat_as_url=True),
            log_safe(str(e)),
        )
        return None

    if not current_user_effective_roles.intersection(required_roles):
        return target_url

    denylist_url_patterns = _normalize_policy_denylist_patterns(policy_settings.get('denylist_url_patterns'))
    if any(fnmatch.fnmatchcase(request_path, pattern) for pattern in denylist_url_patterns):
        return target_url

    return None
